INSERT INTO `faq` VALUES
('17f7f763-b072-4650-a2a0-f7cc2b459ee3','Все ли участники — настоящие экстрасенсы?','Все специалисты прошли строгий отбор и подтвердили свои способности.',8,1),
('389a2a72-38e5-4815-9f18-d118089f1f1d','Сколько стоит консультация экстрасенса?','Стоимость зависит от специалиста и формата проведения. Первичная консультация длится 60 минут. Точную стоимость уточняйте у администратора.',2,1),
('7a25c9fa-e01a-43cd-ba40-f1354bc9979e','Можно ли получить консультацию онлайн?','Да, большинство специалистов проводят консультации как очно, так и онлайн.',3,1),
('8de9ea63-3209-46bf-b922-5869779df8d4','Как записаться на приём к экстрасенсу?','Для записи на приём заполните форму на нашем сайте, указав ваше имя, телефон и краткое описание ситуации. Наш администратор свяжется с вами в течение 24 часов.',1,1),
('989c8899-7317-4d2a-8486-9a3b249d13c4','С какими проблемами можно обратиться?','Наши экстрасенсы помогают в широком спектре вопросов: любовь, здоровье, бизнес, поиск пропавших и многое другое.',6,1),
('99cc3c46-79fc-4cce-9d49-635eae3eede2','Как подготовиться к консультации?','Специальной подготовки не требуется. Рекомендуем заранее сформулировать вопросы.',7,1),
('9a85ad7d-8996-4387-90a4-162b47fd051e','Конфиденциальна ли информация?','Абсолютно. Мы строго соблюдаем конфиденциальность всех обращений.',5,1),
('cfef33ce-8d71-4e07-8102-c4edc76f3a03','Гарантируете ли вы результат?','Мы гарантируем, что с вами будет работать проверенный специалист. Наши экстрасенсы всегда честны в прогнозах.',4,1);
/*!40000 ALTER TABLE `faq` ENABLE KEYS */;
