INSERT INTO `participants` VALUES
('0a1b0a8c-ae8b-4a65-9b05-9c9f2b7c59fb','vlad-cherevatyy','Влад Череватый','Участник 23 сезона','Молодой и сильный экстрасенс, мастер рунической магии и энергетических практик. Создаёт индивидуальные рунические формулы для защиты, привлечения удачи и финансового успеха.','Влад Череватый — победитель 23 сезона проекта «Битва экстрасенсов», ставший известным благодаря яркому образу и нестандартному стилю.\n\nОн позиционирует себя как практик, работающий с тёмной энергетикой и взаимодействием с сущностями. На проекте он демонстрировал уверенность и сильные результаты.\n\nПосле победы Влад активно развивает свою практику и остаётся одной из самых обсуждаемых фигур проекта.','/api/uploads/vlad-cherevatyy-new.jpg','[\"Экстрасенс\",\"Рунолог\"]',1,8,'2026-03-06 17:47:45'),
('510cc3de-0901-490b-bb7e-01257af330de','viktoriya-raidos','Виктория Райдос','Победитель 17 сезона','Экстрасенс-медиум, победительница 17 сезона. Обладает редким даром связи с потусторонним миром. Проводит спиритические сеансы, считывает информацию по фотографиям и предметам, помогает в поиске пропавших людей.','Виктория Райдос — победительница 16 сезона проекта «Битва экстрасенсов», медиум и специалист по работе с родовой памятью. Она родилась в Санкт-Петербурге и имеет философское образование.\n\nЕё подход сочетает интуитивное восприятие и аналитическое мышление. В своей практике она уделяет внимание родовым сценариям, причинно-следственным связям и влиянию прошлого на настоящее.\n\nВо время участия в проекте Виктория демонстрировала стабильные результаты и уверенность, что позволило ей занять первое место. После шоу она активно ведёт практику и участвует в различных проектах.','/api/uploads/viktoriya-raidos-new.jpg','[\"Медиум\",\"Экстрасенс\"]',1,3,'2026-03-06 17:47:45'),
('6511bedc-22c4-4938-8b19-f538a197f4ab','oleg-sheps','Олег Шепс','Участник 18 сезона','Потомственный маг и практикующий оккультист. Владеет техниками церемониальной магии и энергетической защиты. Специализируется на снятии сложных негативных воздействий и создании мощных защитных барьеров.','Олег Шепс — победитель 21 сезона проекта «Битва экстрасенсов», медиум и младший брат Александра Шепса. Он родился в Самаре и с раннего возраста развивал свои способности.\n\nНа проекте он показал уверенные результаты и эмоциональную вовлечённость, что позволило ему одержать победу.\n\nПосле шоу Олег продолжил развивать свою практику и работать с клиентами.','/api/uploads/oleg-sheps-new.jpg','[\"Маг\",\"Оккультист\"]',1,6,'2026-03-06 17:47:45'),
('a6d90f03-6e43-49c6-ad17-3b291f4c05f8','elena-golunova','Елена Голунова','Победитель 16 сезона','Сильнейшая ясновидящая России. Победительница 16 сезона «Битвы экстрасенсов». Работает с энергетикой человека, проводит точную диагностику жизненных ситуаций и помогает найти выход из самых сложных обстоятельств.','Елена Голунова — финалистка 13 сезона проекта «Битва экстрасенсов», получившая широкую известность благодаря своему жёсткому стилю и уверенной подаче. Она родилась в Новосибирске и с раннего возраста, по её словам, сталкивалась с необычным восприятием окружающего мира.\n\nГолунова открыто заявляет, что работает с тёмной энергетикой и родовыми практиками. В своих выступлениях она подчёркивает, что её способности связаны с наследственной линией и передаются по роду. В её подходе особое внимание уделяется причинам происходящего и глубинным процессам.\n\nНа проекте она запомнилась как один из самых прямолинейных участников, демонстрируя уверенное прохождение испытаний и сильный характер. После участия в шоу Елена продолжила частную практику и стала одной из самых узнаваемых фигур проекта.','/api/uploads/elena-golunova-new.jpg','[\"Ясновидящая\",\"Экстрасенс\"]',1,1,'2026-03-06 17:47:45'),
('bff728e9-87bd-4ad4-9226-663b60f94401','zuliya-radzhabova','Зулия Раджабова','Финалист 20 сезона','Целительница и ясновидящая с восточными корнями. Владеет техниками энергетического целительства и духовных практик Востока. Помогает восстановить здоровье, гармонизировать отношения и обрести душевное равновесие.','Зулия Раджабова — победительница 2 сезона проекта «Битва экстрасенсов», одна из первых ярких участниц шоу. Она родом из Дагестана и утверждает, что её способности проявились в детстве.\n\nНа проекте она демонстрировала уверенное прохождение испытаний и точные результаты, что принесло ей победу.\n\nПосле участия в шоу она продолжила частную практику.','/api/uploads/zuliya-radzhabova-new.jpg','[\"Целитель\",\"Ясновидящая\"]',1,7,'2026-03-06 17:47:45'),
('e4b20f5e-d327-4f5a-8d82-c66ab7c9f5b4','aleksandr-sheps','Александр Шепс','Победитель 14 сезона','Один из сильнейших экстрасенсов России, победитель 14 сезона «Битвы экстрасенсов». Обладает мощным даром ясновидения и телепатии. Работает с кармой, прошлыми жизнями и энергетическими потоками.','Александр Шепс — победитель 14 сезона проекта «Битва экстрасенсов», один из самых известных медиумов шоу. Он родился в Самаре и с юного возраста, по его словам, сталкивался с необычными явлениями.\n\nШепс позиционирует себя как медиум, работающий с миром духов. На проекте он демонстрировал уверенное прохождение испытаний и способность получать информацию нестандартным способом.\n\nПосле победы он стал медийной фигурой, продолжил практику и участие в различных проектах.','/api/uploads/aleksandr-sheps-new.jpg','[\"Экстрасенс\",\"Ясновидящий\"]',1,5,'2026-03-06 17:47:45'),
('e9fabf23-fa87-439f-a9c8-902409219269','angelina-izosimova','Ангелина Изосимова','Участница 24 сезона','Потомственная ведьма с уникальным даром чтения судеб. Владеет древними славянскими практиками, работает с родовыми программами и кармическими узлами. Помогает избавиться от негативных воздействий и обрести внутреннюю силу.','Ангелина Изосимова — участница проекта «Битва экстрасенсов», известная своим спокойным и сосредоточенным стилем работы. В ходе участия в шоу она делала акцент на внимательном анализе ситуации и работе с деталями.\n\nВ открытых источниках о её биографии представлено немного информации, однако известно, что она практикует интуитивный подход и работает с ощущением энергетического состояния человека.\n\nНа проекте Ангелина проявила себя как сдержанный участник, предпочитающий аккуратную и последовательную работу. После участия в шоу она продолжила частную практику.','/api/uploads/angelina-izosimova-new.jpg','[\"Ведьма\",\"Целитель\"]',1,2,'2026-03-06 17:47:45'),
('efbd6d96-4c59-448d-a546-c9595a02c26b','nadezhda-shevchenko','Надежда Шевченко','Участница 22 сезона','Ясновидящая и таролог с многолетним опытом. Работает через карты Таро и интуитивное считывание. Специализируется на вопросах любви, карьеры и финансового благополучия. Известна высокой точностью прогнозов.','Надежда Шевченко — финалистка 17 сезона проекта «Битва экстрасенсов», известная своим ярким стилем и использованием ритуальных практик.\n\nНа проекте она привлекла внимание эмоциональностью и нестандартным подходом, часто используя обрядовые элементы и символику. Это стало важной частью её узнаваемого образа.\n\nЕё работа строится на сочетании интуитивного восприятия и ритуальных методов. После участия в шоу она продолжила частную практику.','/api/uploads/nadezhda-shevchenko-new.jpg','[\"Ясновидящая\",\"Таролог\"]',1,4,'2026-03-06 17:47:45');
