INSERT INTO `reviews` VALUES
('0058b6c0-c683-4309-aa19-77cfcb617757','zuliya-radzhabova','Олег Д.','Казань, 45 лет','Зулия восстановила моё биополе после тяжёлой операции. Восстановление пошло гораздо быстрее.',5,1,'2026-03-06 17:47:45'),
('04a4df32-eaa6-4461-af90-94ea19a8e556','elena-golunova','Кристина, 25','','Я жила в постоянном, липком страхе и паранойе. Мой бывший парень никак не мог смириться с нашим окончательным расставанием. Он маниакально преследовал меня, часами караулил у подъезда, присылал жуткие голосовые сообщения с угрозами, резал шины на моей машине по ночам. Полиция только разводила руками — говорили, что нет состава преступления, вот когда убьет, тогда и приходите. Я панически боялась просто выходить из дома в магазин. В полном отчаянии я стала искать сильную магическую защиту. По многочисленным отзывам поняла, что сибирская ведьма Елена Голунова — это именно тот властный человек, который может жестко поставить на место такого неадеквата. Я нашла ее официальный контакт в сети и записалась на прием. Елена выслушала меня и провела сложный обряд зеркальной защиты. Она уверенно сказала, что теперь абсолютно всё зло, которое он мне желает и делает, будет моментально возвращаться к нему самому в троекратном размере. Я не знаю, как именно работает эта магия, но через неделю он сильно сломал ногу, потом у него начались серьезные проблемы с законом на работе, и он навсегда исчез из моей жизни. Я наконец-то дышу свободно и не оглядываюсь на улице!',5,1,'2026-03-23 12:19:08'),
('052a2d37-8f02-4c1f-874f-4f6ce2a9bc3e','nadezhda-shevchenko','Юлия М.','Москва, 30 лет','Надежда сделала расклад Таро, который оказался пророческим. Всё, что она предсказала, сбылось в течение полугода.',5,1,'2026-03-06 17:47:45'),
('0865c54a-aca1-47b0-b750-a4a9fd7b5a0c','nadezhda-shevchenko','Наталья Б.','Тюмень, 31 год','Помогла найти потерянное украшение через карты. Я была в шоке от точности.',5,1,'2026-03-06 17:47:45'),
('0887d811-5cdc-49ed-afc3-6cd7510ec3d0','zuliya-radzhabova','Михаил Н.','Екатеринбург, 51 год','Обращался с проблемой бессонницы. После двух сеансов у Зулии сплю как младенец.',5,1,'2026-03-06 17:47:45'),
('09123fea-3adc-4f49-8e1d-c3e8eb1e9abb','vlad-cherevatyy','Ирина М.','Краснодар, 36 лет','Молодой, но очень талантливый. Влад видит ауру и точно определяет проблемы.',5,1,'2026-03-06 17:47:45'),
('0b6b15b2-6074-44f2-8425-5c7180d61575','oleg-sheps','Наталья Т.','Красноярск, 37 лет','Олег Шепс — единственный, кто смог помочь с нашей проблемой. Профессионал.',4,1,'2026-03-06 17:47:45'),
('0c2d2956-c8a4-40ff-a5d0-6444df6be9cb','nadezhda-shevchenko','Ирина Г.','Красноярск, 36 лет','Надежда предсказала мне беременность, когда я уже потеряла надежду. Через два месяца я узнала, что жду ребёнка.',5,1,'2026-03-06 17:47:45'),
('0c658733-4575-4cfb-a155-535ac3b45955','aleksandr-sheps','Михаил К.','Москва, 44 года','Александр Шепс — легенда Битвы экстрасенсов. На консультации он описал мою проблему за первые 30 секунд, без единого вопроса.',5,1,'2026-03-06 17:47:45'),
('0c7bab28-1d47-440c-b71d-52603541cd1e','angelina-izosimova','Анна С.','Ростов-на-Дону, 26 лет','После работы с Ангелиной мои панические атаки прекратились. Она нашла их энергетическую причину.',5,1,'2026-03-06 17:47:45'),
('0d2525f9-016c-4010-b7f2-9bd9db08e106','elena-golunova','Алексей, 39','','За один неполный год я умудрился попасть в четыре очень серьезные автомобильные аварии. Причем я опытный водитель с двадцатилетним безаварийным стажем, всегда езжу крайне аккуратно и по правилам. Машины разбивались просто в хлам, я чудом оставался жив, отделываясь тяжелыми переломами и сотрясениями мозга. Страховые компании уже отказывались со мной работать, внося в черные списки. Я стал панически бояться садиться за руль, начал ездить на такси. Мой лучший друг посоветовал обратиться к эзотерике, сказал, что это очень похоже на наведенное проклятие. Я начал гуглить \"экстрасенс новосибирск елена голунова\" и искать, как к ней можно попасть на консультацию. Оставил подробную заявку через официальную форму. На приеме Елена сразу, глядя мне в глаза, увидела истинную причину. Оказалось, я случайно перешел дорогу очень влиятельному и злому человеку в бизнесе, и он заказал на меня порчу на смерть именно через аварии на дороге. Елена сняла этот страшный негатив и поставила на меня мощную защиту. С тех пор прошло почти два спокойных года. Я снова вожу машину с удовольствием, и ни одной, даже самой мелкой царапины на бампере!',5,1,'2026-03-23 12:19:08'),
('0eecb353-22b2-43dc-98f3-26f716ba53e4','vlad-cherevatyy','Анна Т.','Красноярск, 31 год','Влад Череватый создал рунический амулет для моей дочери на удачу в учёбе. Результаты улучшились.',4,1,'2026-03-06 17:47:45'),
('0f567968-c585-430a-bc09-419c6b2a9de6','viktoriya-raidos','Елена Б.','Екатеринбург, 41 год','Виктория провела сеанс связи с моей бабушкой. Информация, которую она передала, знали только мы двое.',5,1,'2026-03-06 17:47:45'),
('121e0fae-352b-41d7-baca-eba333cb4fa5','zuliya-radzhabova','Лариса М.','Москва, 48 лет','Зулия исцелила мою хроническую боль в спине, которая мучила 10 лет. Врачи не могли помочь, а она смогла.',5,1,'2026-03-06 17:47:45'),
('12d453c7-b2ea-4787-a33a-585a66ec3893','angelina-izosimova','Оксана Д.','Новосибирск, 31 год','Ангелина Изосимова видит то, что скрыто от других. Она определила негатив на моей семье и провела мощный обряд очищения.',5,1,'2026-03-06 17:47:45'),
('13cbf47b-a9d5-4dc9-afe7-c180d4bbbf05','elena-golunova','Андрей, 44','','Меня неожиданно и подло обвинили в серьезном экономическом преступлении, которого я никогда не совершал. Бывшие партнеры по бизнесу подставили меня по полной программе, виртуозно сфабриковали финансовые документы. Мои дорогие адвокаты давали крайне неутешительные прогнозы — мне реально светил большой срок с конфискацией. Я был в полном отчаянии, не знал, что делать, семья в слезах готовилась к худшему исходу. Жена тайком от меня начала искать ясновидящую, чтобы хоть как-то прояснить ситуацию. Нашла официальную страницу Елены Голуновой, узнала, сколько стоят ее услуги, и записала меня на прием в Москве. Я шел туда без всякой надежды, просто чтобы успокоить истерзанную жену. Но то, что произошло в кабинете, не поддается никакой здравой логике. Экстрасенс в мельчайших деталях описала схему, по которой меня подставили, назвала имена людей, которые прятались в тени. Она дала четкий совет, где именно искать недостающие черновые документы, доказывающие мою абсолютную невиновность. И мы их нашли! В старом пыльном архиве, о котором все давно забыли. Суд меня полностью оправдал. Эта помощь была поистине бесценной.',5,1,'2026-03-23 12:19:08'),
('17735733-d983-45b1-b37f-d779d5ad2d35','oleg-sheps','Сергей М.','Ростов-на-Дону, 50 лет','Олег провёл обряд на защиту бизнеса. Завистники перестали влиять на мои дела.',5,1,'2026-03-06 17:47:45'),
('1786d8be-cf10-4b9e-879e-b6d50772a12c','vlad-cherevatyy','Олег С.','Пермь, 39 лет','Рунические формулы Влада — это искусство. Рекомендую всем.',5,1,'2026-03-06 17:47:45'),
('189a279d-12b1-413c-9c90-0d021ff0eac9','zuliya-radzhabova','Дарья Н.','Пермь, 27 лет','После работы с Зулией ушла хроническая усталость, появилась энергия на жизнь.',5,1,'2026-03-06 17:47:45'),
('1f3c4b5f-45b0-4ccb-9a92-6524edf76799','elena-golunova','Екатерина, 27','','Мой семилетний сын начал просыпаться каждую божью ночь с дикими, истеричными криками. Он показывал пальцем в темный угол комнаты и плакал, что там стоит страшный черный человек и смотрит на него. Сначала мы с мужем думали, что это просто бурные детские фантазии и кошмары, водили к детскому неврологу, пили легкие успокоительные. Но становилось только хуже, ребенок начал таять на глазах, отказывался есть, боялся оставаться один даже ярким днем. Я была на грани нервного срыва. На одном форуме мамочек мне в личные сообщения посоветовали обратиться за нетрадиционной помощью. Я долго искала информацию, сверяла адреса. Выбор пал на Елену. Нашла ее контактный номер, написала длинное умоляющее сообщение. Администраторы вошли в наше тяжелое положение и нашли для нас окошко для онлайн-встречи. Елена Голунова работала с нами дистанционно. Она объяснила, что ребенок очень энергетически чувствительный и реально видит то, что мы не замечаем. Провела чистку квартиры и поставила мощную защиту на сына. В ту же ночь он впервые за долгое время спал спокойно до самого утра.',5,1,'2026-03-23 12:19:08'),
('222224f1-f91d-41b6-aae7-761c166e5779','zuliya-radzhabova','Екатерина Р.','Новосибирск, 35 лет','Восточная мудрость Зулии чувствуется в каждом слове. Она не просто лечит — она учит жить в гармонии.',5,1,'2026-03-06 17:47:45'),
('232718ff-a109-4c1c-8e50-7d1c124c783d','angelina-izosimova','Светлана П.','Пермь, 36 лет','Благодаря Ангелине наладила отношения с мужем и свекровью. Она увидела корень проблемы.',5,1,'2026-03-06 17:47:45'),
('2494901a-71b0-4066-b314-e9cb002aa93f','zuliya-radzhabova','Анна В.','Санкт-Петербург, 32 года','Зулия Раджабова обладает удивительным даром целительства. После её сеанса я почувствовала прилив сил и энергии.',5,1,'2026-03-06 17:47:45'),
('24d07410-faf8-479c-a3a4-e3c44a83bfb0','vlad-cherevatyy','Сергей Р.','Казань, 38 лет','Обратился к Владу для защиты бизнеса. Его рунический ритуал оказался мощнее, чем я ожидал.',5,1,'2026-03-06 17:47:45'),
('2543e34c-c1c2-439c-9763-ea1723788d40','angelina-izosimova','Наталья Г.','Воронеж, 39 лет','Ангелина — настоящая потомственная ведьма. Её славянские ритуалы поразительно сильны.',5,1,'2026-03-06 17:47:45'),
('2827e092-dac6-4868-853e-6559aed26632','angelina-izosimova','Максим Л.','Красноярск, 35 лет','Мощный ритуал защиты от Ангелины — и дела в бизнесе пошли в гору.',5,1,'2026-03-06 17:47:45'),
('2b78a588-646e-47b9-a351-548749750e61','vlad-cherevatyy','Виктор Н.','Воронеж, 48 лет','Эффективный и быстрый. Влад решил проблему, с которой я ходил к другим специалистам годами.',5,1,'2026-03-06 17:47:45'),
('2de6d40d-e727-41ac-b884-1ce1fe90dbb5','elena-golunova','Анна, 34','','Я была в полном отчаянии, когда поняла, что в нашей семье мужчины уходят один за другим. Сначала дед, потом отец, а когда брат попал в странную аварию, я поняла — это не просто злой рок. Знакомые посоветовали не тянуть и обратиться к специалисту, но я очень долго сомневалась, боялась нарваться на шарлатанов. Искала информацию в интернете, читала отзывы реальных людей, пока не наткнулась на имя экстрасенса Елены Голуновой. Сразу почувствовала, что мне нужна именно она. Нашла официальный сайт, оставила заявку на прием. Ждала ответа дня три, уже думала, что не получится попасть к ней. Но мне перезвонили! Консультация перевернула мою жизнь. Елена Валерьевна с первых минут сказала такие вещи о моем брате, которые никто, кроме нашей семьи, знать физически не мог. Она провела огромную работу. С тех пор прошло полгода. Брат полностью поправился, в семье наступило спокойствие. Я безмерно благодарна этой потрясающей женщине за то, что она помогла и вытащила нас из этого бесконечного кошмара.',5,1,'2026-03-23 12:19:08'),
('30661994-b4f2-42e1-8bc5-ec9b6a5e6101','aleksandr-sheps','Ольга М.','Екатеринбург, 29 лет','На консультации Александр описал человека, который причинял мне вред. Описание совпало до мельчайших деталей.',5,1,'2026-03-06 17:47:45'),
('35f3b3fd-a80a-4b96-af4a-da172c165b38','elena-golunova','Юлия, 29','','Семь долгих лет мы с любимым мужем пытались завести ребенка. Прошли абсолютно все возможные медицинские обследования, сменили пять платных клиник, сделали два мучительных ЭКО — и все безрезультатно. Врачи только разводили руками и говорили: \"Вы оба абсолютно здоровы, пробуйте еще, ждите\". А у меня уже не было ни моральных, ни физических сил на эти ожидания. Я каждую ночь горько плакала в подушку, глядя на чужих детей. В какой-то момент я поняла, что традиционная медицина тут бессильна. Стала искать информацию про сильных экстрасенсов, читала отзывы реальных людей ночами напролет. Поняла, что внутренне доверяю только одному человеку. Елена Голунова — официальный сайт, короткая заявка, томительное ожидание своей очереди. На приеме Елена Валерьевна была сурова, но очень справедлива. Она увидела глубокую старую обиду моей матери на отца, которая неосознанно энергетически блокировала мое собственное материнство. Мы долго и тяжело работали над этим, я выполняла сложные духовные задания. Спустя четыре месяца после нашей совместной работы я увидела заветные две полоски на тесте! Сейчас нашей долгожданной доченьке уже полгода.',5,1,'2026-03-23 12:19:08'),
('37aa2cb9-ec38-47c6-aedd-b7db393aeb79','elena-golunova','Михаил, 45','','Всё началось с того, что мой бизнес, который я строил десять лет потом и кровью, начал рушиться буквально на глазах. Поставщики кидали, крупные клиенты уходили без объяснения причин, проверки шли одна за другой. Я не спал ночами, залез в огромные долги и кредиты. Жена, видя мое ужасное состояние, сама начала искать ясновидящую. Она всегда смотрела проект \"Битва сильнейших\", верила в это и настояла, чтобы мы попробовали. Я скептик до мозга костей, но терять было уже нечего. Мы узнали, сколько стоит прием, нашли официальный контакт и оформили запись. Когда я оказался у Голуновой в Москве, мой скептицизм испарился в первые же пять минут разговора. Она не задавала никаких наводящих вопросов, просто жестко и четко описала моего бывшего партнера, который, как оказалось, провел ритуал на разорение. Елена дала четкие инструкции, что делать дальше. Я выполнил всё до мелочей. Сейчас мои деньги снова работают, долги закрыты, а тот партнер сам оказался под следствием.',5,1,'2026-03-23 12:19:08'),
('392a2e63-cd73-4656-92c7-963814804e5a','oleg-sheps','Дмитрий Г.','Воронеж, 53 года','Обратился для чистки энергетики дома. Результат почувствовала вся семья.',5,1,'2026-03-06 17:47:45'),
('3ac137ff-6912-4a63-80c0-b7a061fbc103','nadezhda-shevchenko','Светлана А.','Краснодар, 44 года','Расклад Надежды показал, что мой муж мне верен. Я перестала мучиться сомнениями.',5,1,'2026-03-06 17:47:45'),
('3c73695d-ba61-48c1-8f4a-0da4b7be63f4','oleg-sheps','Роман В.','Омск, 41 год','Защитные ритуалы Олега — самые сильные из тех, что я встречал.',5,1,'2026-03-06 17:47:45'),
('413f559e-0648-44ac-b018-0a12cc355a79','elena-golunova','Роман, 28','','В свои 28 лет я внезапно и без видимых причин потерял абсолютно всякий интерес к жизни. Уволился с престижной, высокооплачиваемой работы, расстался с прекрасной невестой, полностью перестал общаться с друзьями. Я просто лежал целыми днями на диване в темной комнате и тупо смотрел в потолок. Врачи уверенно ставили клиническую депрессию, выписывали горсти антидепрессантов, но они делали из меня бесчувственного овоща. Моя мама в слезах умоляла меня попробовать нетрадиционные методы лечения. Она сама нашла контакты, выяснила, как принимает экстрасенс Елена Голунова, и организовала мне онлайн-консультацию. Мне было абсолютно все равно, я согласился только ради спокойствия матери. Но во время видеозвонка произошло нечто совершенно необъяснимое. Елена словно заглянула мне прямо в душу. Она увидела, что я по глупости забрал на себя чужой тяжелый кармический груз во время туристической поездки в аномальную зону пару лет назад. Она провела сложный ритуал отсечения этой связи. Буквально на следующее утро я проснулся с ясной головой, полным сил и забытым желанием жить. Сейчас я открыл свой успешный бизнес и снова по-настоящему счастлив.',5,1,'2026-03-23 12:19:08'),
('430e27b8-e7c5-4ac0-949f-4d1adc451626','zuliya-radzhabova','Надежда К.','Красноярск, 43 года','Зулия работает с чакрами так, как никто другой. Её восточные техники невероятно эффективны.',4,1,'2026-03-06 17:47:45'),
('4403ab9e-8604-48b5-a4de-23d49c3bcecc','oleg-sheps','Андрей Л.','Новосибирск, 38 лет','Олег изготовил для нашей семьи защитный амулет. С тех пор в доме царит мир и покой.',5,1,'2026-03-06 17:47:45'),
('466ab024-c70c-4353-a120-3641ab27c7bb','aleksandr-sheps','Виктор Д.','Казань, 52 года','Александр помог мне принять решение, которое я откладывал годами. Он увидел оба варианта развития событий.',5,1,'2026-03-06 17:47:45'),
('4b911668-3886-4918-8bd6-82b65a5c7f97','elena-golunova','Алиса, 26','','Наша долгожданная свадьба была полностью, до основания разрушена за неделю до самого торжества. Мой жених внезапно и без причин попал в реанимацию с неизвестной врачам инфекцией, выбранный нами ресторан сгорел ночью дотла, а у меня из закрытой квартиры украли дорогущее свадебное платье. Казалось, весь мир ополчился против нашего союза. Мама жениха была абсолютно уверена, что это сильный сглаз или порча от бывшей, очень завистливой девушки моего суженого. Мы решили не рисковать его жизнью и срочно обратиться к профессионалу. Узнали через знакомых, как записаться, сколько стоят услуги. Елена Голунова приняла нас по видеосвязи, так как я ни на шаг не могла отойти от жениха в больнице. Она сразу подтвердила, что на нас была сделана очень сильная, профессиональная порча на разрушение союза и болезни. Елена провела дистанционную чистку и велела мне самой сделать несколько простых, но очень важных защитных ритуалов. Вы не поверите, но жениху стало значительно лучше на следующий же день! Врачи были просто в шоке от такой быстрой, нереальной динамики выздоровления. Свадьбу мы в итоге сыграли очень скромно, в кругу семьи, но самое главное — мы вместе, живы и счастливы!',5,1,'2026-03-23 12:19:08'),
('4c970533-78d0-4b25-81ae-a98780f3a8e7','oleg-sheps','Елена Н.','Санкт-Петербург, 33 года','Олег Шепс снял порчу, которая мучила меня два года. Другие экстрасенсы даже не могли её обнаружить.',5,1,'2026-03-06 17:47:45'),
('4fdc9eee-daa0-40a9-b7fd-af88a5ec5098','vlad-cherevatyy','Кристина Б.','Тюмень, 25 лет','Влад — экстрасенс нового поколения. Его подход современный, но сила древняя.',5,1,'2026-03-06 17:47:45'),
('51099d11-5b7b-4899-8b7d-c4ce45fcff28','viktoriya-raidos','Наталья К.','Краснодар, 32 года','Обратилась с вопросом о будущем отношений. Прогноз сбылся через три месяца с точностью до деталей.',5,1,'2026-03-06 17:47:45'),
('56a1ec4d-d09a-4b6e-8731-d7f6e6232343','elena-golunova','Владимир, 42','','Кризис среднего возраста ударил по мне со страшной, разрушительной силой. В 42 года я с ужасом понял, что живу абсолютно чужую, навязанную мне жизнь. От работы физически тошнит, семья стала просто скучной привычкой, а внутри — звенящая, невыносимая пустота. Я начал по вечерам сильно пить, появились навязчивые мысли бросить всё, развестись и уехать жить в глушь одному. Пытался найти ответы и помощь у модных психологов, но это были просто пустые, долгие разговоры ни о чем. Мой старый друг посоветовал обратиться к человеку, который реально видит скрытое от обычных глаз. Я долго и скептически изучал официальный сайт Елены Голуновой, читал разные отзывы. Наконец, пересилил себя и оформил онлайн-встречу. Елена Валерьевна, известная мне по проекту битва сильнейших, с первых же суровых слов расставила всё по своим местам в моей голове. Она жестко указала мне на мое истинное предназначение, которое я упорно и трусливо игнорировал всю свою жизнь в угоду родителям и обществу. Она дала мне мощный энергетический толчок и вернула уверенность в себе. Я кардинально сменил сферу деятельности, занялся реставрацией старинной мебели. И знаете, жизнь заиграла такими яркими красками, о которых я даже и не мечтал в юности.',5,1,'2026-03-23 12:19:08'),
('56e10622-c032-4e57-bfc7-52aed5660b68','aleksandr-sheps','Елена С.','Новосибирск, 38 лет','Победитель 14 сезона — и это заслуженно. Его дар невозможно подделать.',5,1,'2026-03-06 17:47:45'),
('592af255-92a4-43b5-a3ea-c6deb8e6ff13','oleg-sheps','Мария А.','Краснодар, 28 лет','Олег определил источник негатива в моей жизни и устранил его за один сеанс.',5,1,'2026-03-06 17:47:45'),
('5990a79b-241c-4cb9-9d4d-35dd3b2f65de','aleksandr-sheps','Марина Г.','Воронеж, 33 года','Три консультации у Александра — и моя жизнь полностью изменилась. Он видит корень проблем.',4,1,'2026-03-06 17:47:45'),
('617041c0-2bf9-401f-82e5-b548e8996810','viktoriya-raidos','Дмитрий Л.','Красноярск, 43 года','Виктория Райдос — настоящий профессионал. Её работа точна и деликатна.',4,1,'2026-03-06 17:47:45'),
('6250612d-8e2f-4ed0-b8da-211d10dc35db','aleksandr-sheps','Кристина Д.','Тюмень, 27 лет','Один из сильнейших экстрасенсов, с которыми я сталкивалась. Результат ощутим сразу.',5,1,'2026-03-06 17:47:45'),
('65bd741b-4921-4ff3-8846-0df0b8db85e0','nadezhda-shevchenko','Алексей Р.','Воронеж, 48 лет','Профессиональный подход, глубокий анализ ситуации. Надежда — один из лучших тарологов.',4,1,'2026-03-06 17:47:45'),
('68013822-020b-4cca-96ad-4f1c7460c303','viktoriya-raidos','Мария Р.','Казань, 28 лет','На сеансе Виктория описала мою квартиру, людей из моего окружения — всё по фотографии. Точность поразительная.',5,1,'2026-03-06 17:47:45'),
('6ae7706a-9c76-4cdf-a65a-75faa3e1567a','viktoriya-raidos','Ольга Т.','Санкт-Петербург, 34 года','Виктория считала по фотографии моего пропавшего брата информацию, которая помогла его найти. Невероятный дар.',5,1,'2026-03-06 17:47:45'),
('6b22e663-b6a4-4306-b9a2-2105e4f04cb9','elena-golunova','Дарья, 32','','В нашем новом, долгожданном загородном доме начали происходить пугающие и странные вещи. Сначала мы с мужем списывали непонятные шаги на чердаке на мышей, а холодные, резкие сквозняки — на плохую строительную изоляцию. Но когда начали сами по себе включаться электроприборы среди ночи и с грохотом падать картины со стен, стало по-настоящему страшно. Мой пес сутками сидел забившись под кроватью и жалобно скулил, отказываясь есть. Жить там стало просто невыносимо, мы думали съезжать. Я начала гуглить, кто может помочь очистить дом от этой чертовщины. Поисковик выдал информацию, где принимает экстрасенс Елена Голунова. Я заполнила форму на сайте, чтобы связаться с ней. Мне перезвонили и назначили дату. Елена приехала к нам лично. Это было невероятно мощно и жутко одновременно. Она нашла гнилой подклад в фундаменте дома — кто-то из обиженных рабочих во время стройки заложил туда заговоренные предметы на разорение и беды хозяевам. После ее ритуалов дом словно выдохнул и ожил. Стало тепло, уютно, собака снова стала веселой и активной. Мы наконец-то можем спать спокойно в своем доме.',5,1,'2026-03-23 12:19:08'),
('7029c159-11a9-433a-9d0a-a9d5dc6b1379','angelina-izosimova','Игорь Н.','Казань, 48 лет','Обратился к Ангелине по рекомендации друга. Она провела диагностику рода и нашла источник наших семейных проблем.',5,1,'2026-03-06 17:47:45'),
('74a81ba5-e32b-480e-8a52-244b6583f3eb','viktoriya-raidos','Ирина Н.','Самара, 37 лет','Удивительный медиум. Прикоснулась к моему кольцу и рассказала всю историю моей семьи.',5,1,'2026-03-06 17:47:45'),
('78d20c99-73cd-4240-8c12-64f0cc094112','aleksandr-sheps','Игорь Т.','Самара, 40 лет','Благодаря Александру нашёл своё призвание. Он увидел мой потенциал, о котором я сам не догадывался.',5,1,'2026-03-06 17:47:45'),
('7b90711a-4b47-4244-947c-d62db10e0c27','aleksandr-sheps','Анна Р.','Санкт-Петербург, 31 год','Александр увидел мою прошлую жизнь и объяснил, почему я повторяю одни и те же ошибки. После работы с ним паттерн сломался.',5,1,'2026-03-06 17:47:45'),
('7bb1c907-88e0-4eb9-970e-e77b4a7b5c4c','nadezhda-shevchenko','Андрей К.','Казань, 42 года','Обратился к Надежде с финансовыми проблемами. Она определила неблагоприятный период и рекомендовала подождать. Через два месяца всё наладилось.',5,1,'2026-03-06 17:47:45'),
('80531922-008c-45bc-936a-17e4024a0f9d','zuliya-radzhabova','Ирина Б.','Тюмень, 46 лет','Зулия Раджабова — целитель от бога. Её дар уникален.',5,1,'2026-03-06 17:47:45'),
('84d8148f-f11d-438b-938a-b5a6eb7415bc','angelina-izosimova','Людмила В.','Краснодар, 50 лет','Ангелина помогла моей дочери выйти замуж — сняла венец безбрачия, который тянулся по женской линии.',5,1,'2026-03-06 17:47:45'),
('85cf29e1-67e2-41b9-a8d4-35581e021e2f','elena-golunova','Мария, 35','','Бесконечные долги просто душили меня со всех сторон, не давая вздохнуть. Я брала новые микрозаймы, чтобы закрыть старые кредиты, работала на трех работах без выходных, но деньги словно утекали сквозь пальцы в никуда. Казалось, я попала в какую-то черную воронку бедности, из которой нет выхода. В какой-то момент появились самые страшные мысли от бессилия, настолько я устала бороться за выживание. Знакомая, видя мое жуткое состояние, дала мне контакт и сказала просто: \"Напиши ей, она вытаскивает и не из такого\". Это была ясновидящая Елена Голунова. Я очень сомневалась, боялась обмана, но все же решила рискнуть. Узнала стоимость приема, заняла последнюю возможную сумму у брата и записалась. Елена Валерьевна оказалась очень прямолинейным, волевым человеком. Она с ходу заявила, что у меня наглухо перекрыт финансовый канал из-за старой порчи на нищету, которую сделала бывшая свекровь. Работа была тяжелой физически и морально, я четко выполняла все ее строгие указания. Буквально через месяц мне неожиданно предложили высокооплачиваемую должность, о которой я даже мечтать боялась. Сейчас я полностью свободна от всех долгов и живу спокойно.',5,1,'2026-03-23 12:19:08'),
('86253876-4d86-4da1-a367-293cdf2ec8e5','oleg-sheps','Вадим К.','Москва, 46 лет','Олег создал для меня защитный ритуал после серии неудач в бизнесе. Через месяц подписал три крупных контракта.',5,1,'2026-03-06 17:47:45'),
('872a969b-66c2-4f12-aeed-15e66e4a123f','zuliya-radzhabova','Марина Л.','Воронеж, 34 года','Помогла моему сыну справиться с заиканием. Три сеанса — и он говорит свободно.',5,1,'2026-03-06 17:47:45'),
('89ec4166-34f0-48b4-8a17-566f051bc3af','elena-golunova','Елена, 36','','Я всегда нутром чувствовала, что свекровь меня тихо недолюбливает, но старалась не придавать этому значения ради мира в семье. Мы жили отдельно, виделись редко. Однако со временем отношения с любимым мужем стали резко и необъяснимо портиться. Он начал придираться по малейшим пустякам, стал необоснованно агрессивным, полностью перестал обращать на меня внимание как на любимую женщину. А однажды я случайно нашла в кармане его зимней куртки странный холщовый мешочек с сухими травами и землей. Тут-то мне и стало по-настоящему не по себе. Я стала искать в сети, что это может значить. Наткнулась на страшную информацию про кладбищенский приворот и черные рассорки. Решила, что медлить больше нельзя ни дня. Узнала номер телефона, по которому можно записаться к сильной колдунье Елене Голуновой. Цена приема меня совершенно не смутила, я спасала свою семью и мужа. Елена сразу подтвердила мои опасения — свекровь делала магические остуды, чтобы развести нас любой ценой. Мы провели глубокую чистку, я поставила зеркальную защиту на наш брак. Муж изменился до неузнаваемости, снова стал тем заботливым человеком, за которого я выходила замуж. А свекровь внезапно переехала жить в другой город и больше не лезет в нашу жизнь.',5,1,'2026-03-23 12:19:08'),
('930d3229-3cbf-4f89-b32c-7a993f57a486','angelina-izosimova','Елена К.','Москва, 37 лет','Ангелина нашла причину моих постоянных неудач — оказалось, родовое проклятие. После её работы словно камень с души упал.',5,1,'2026-03-06 17:47:45'),
('93796df9-7596-4b19-a43f-8622ba25ae55','oleg-sheps','Виктор С.','Самара, 42 года','Индивидуальный оберег от Олега — это мощная вещь. Ношу его уже год, жизнь изменилась.',5,1,'2026-03-06 17:47:45'),
('9f1e1ee6-d9aa-4dc2-a9c0-c99e8ff49bf8','aleksandr-sheps','Павел С.','Красноярск, 49 лет','Александр определил причину конфликтов в моей семье на кармическом уровне.',5,1,'2026-03-06 17:47:45'),
('9fea5e64-c9bb-4831-bf8a-d0737f9d7ace','vlad-cherevatyy','Артём К.','Москва, 29 лет','Влад Череватый — молодой, но невероятно сильный экстрасенс. Его рунический амулет реально работает — удача пришла буквально в первую неделю.',5,1,'2026-03-06 17:47:45'),
('a082a87c-d3e6-418b-bf0d-011414d6ac13','elena-golunova','Марина, 43','','Узнать о грязной измене мужа — это как получить неожиданный удар ножом в спину. Но когда я через общих знакомых узнала, что его молодая любовница обратилась к черной магии, чтобы окончательно увести его из семьи, мне стало по-настоящему страшно за его жизнь. Он стал сам на себя не похож: сильно похудел, перестал спать, постоянно болел непонятными простудами, но тянулся к ней как привязанный на невидимом поводке. Я поняла, что обычными слезами и уговорами тут точно не помочь. Стала внимательно изучать отзывы в интернете и искать сильного, проверенного мастера. Ясновидящая Елена Голунова сразу вызвала у меня доверие своей невероятной силой и бескомпромиссностью. Я нашла ее официальный сайт, уточнила стоимость приема в Москве и записалась на ближайшую дату. Елена Валерьевна подтвердила наличие черного приворота на муже, сделанного дилетантом, что было еще опаснее. Работа была очень долгой и тяжелой, мне самой пришлось многое переосмыслить в своем поведении. Но мы справились с этой бедой. Любовница навсегда исчезла из нашей жизни, муж восстановился физически, просил прощения на коленях со слезами. Наша семья спасена и сохранена.',5,1,'2026-03-23 12:19:08'),
('a4d4cc54-4027-4a16-9205-d10d3915b51d','zuliya-radzhabova','Виктория С.','Ростов-на-Дону, 29 лет','Зулия помогла наладить отношения в нашей семье. Она видит невидимые связи между людьми.',5,1,'2026-03-06 17:47:45'),
('a7a0ff92-f292-4429-a1f4-911a0c113f08','vlad-cherevatyy','Дмитрий В.','Самара, 45 лет','Обратился к Владу скептиком. Он описал мою ситуацию так точно, что скептицизм испарился.',5,1,'2026-03-06 17:47:45'),
('aa6704a8-f6a5-49a6-9dd5-cf51c903d3bd','nadezhda-shevchenko','Олег В.','Екатеринбург, 51 год','Надежда помогла наладить отношения с взрослым сыном. Она увидела корень нашего конфликта.',5,1,'2026-03-06 17:47:45'),
('ac4fd1f9-1164-4b7b-922c-4466013824b7','nadezhda-shevchenko','Виктория Д.','Санкт-Петербург, 35 лет','Надежда Шевченко помогла мне принять решение о смене карьеры. Расклад показал, что это лучшее время для перемен — и это было абсолютно верно.',5,1,'2026-03-06 17:47:45'),
('ac523ed0-d549-4940-a3fa-7f889645f9ae','elena-golunova','Сергей, 55','','Мое личное обращение к этому выдающемуся человеку было связано с очень деликатной, опасной и сложной бизнес-ситуацией, о которой я до сих пор не могу говорить открыто и в деталях. На кону стояли не только моя многолетняя деловая репутация и огромные деньги, но и физическая безопасность всей моей семьи. Мои беспринципные конкуренты играли не по правилам, используя мощное, целенаправленное негативное воздействие через черных магов. Я человек очень прагматичный, привык верить только цифрам, но когда факты говорят сами за себя, приходится верить в невидимое. Изучил официальный сайт, посмотрел отзывы серьезных людей. Елена Голунова — это не просто известный экстрасенс с экрана телевизора, это настоящий, несгибаемый воин света. Попасть на прием было крайне непросто, запись на месяцы вперед, но мне пошли навстречу из-за критичной срочности вопроса. То, как она работает, вызывает глубочайшее, искреннее уважение. Она не только быстро нейтрализовала нависшую угрозу, но и поставила такую железобетонную защиту на мой бизнес и близких, что теперь любые нападки и происки конкурентов просто отскакивают от меня. Я искренне благодарен Елене Валерьевне за ее титанический труд, абсолютную честность и невероятную силу. Она реально спасает человеческие судьбы на краю пропасти.',5,1,'2026-03-23 12:19:08'),
('ad4ca00b-1623-426f-8b1d-cf416d1a1a87','viktoriya-raidos','Алексей Г.','Ростов-на-Дону, 50 лет','Виктория помогла раскрыть обман в бизнесе, считав информацию по фото партнёра.',5,1,'2026-03-06 17:47:45'),
('ae0df328-a9cf-4769-a256-dced38b7bc57','oleg-sheps','Татьяна Р.','Казань, 40 лет','Потомственный маг — это ощущается. Олег работает на совершенно другом уровне.',5,1,'2026-03-06 17:47:45'),
('aebfcf2f-95e3-45ec-9819-ffeb61cdf52b','vlad-cherevatyy','Ольга Л.','Новосибирск, 27 лет','Влад за пять минут определил сглаз и снял его. Я была в шоке от скорости и точности.',5,1,'2026-03-06 17:47:45'),
('aed17880-0201-42c0-8435-13520f457f37','oleg-sheps','Ольга Д.','Екатеринбург, 45 лет','Обращалась к Олегу для защиты дочери перед свадьбой. Всё прошло прекрасно, никакого негатива.',5,1,'2026-03-06 17:47:45'),
('b80c8498-c4bb-4134-b47e-f551416427fb','aleksandr-sheps','Наталья В.','Краснодар, 36 лет','Александр Шепс читает людей как открытую книгу. Его телепатические способности невероятны.',5,1,'2026-03-06 17:47:45'),
('b856942b-3db0-4cfd-a520-25e8faa9c3dc','viktoriya-raidos','Антон М.','Москва, 39 лет','Виктория Райдос передала мне послание от ушедшего отца. Детали были настолько точны, что сомнений не осталось — это был он.',5,1,'2026-03-06 17:47:45'),
('b9a7f3f3-f396-4d87-8064-eada1ea566ff','nadezhda-shevchenko','Роман Н.','Самара, 33 года','Точность прогнозов Надежды — 100%. Обращался трижды, каждый раз — в точку.',5,1,'2026-03-06 17:47:45'),
('bc898904-9237-4352-b4e7-9abbe3f56f58','aleksandr-sheps','Алексей Н.','Пермь, 43 года','Александр Шепс — мастер своего дела. Его помощь бесценна.',5,1,'2026-03-06 17:47:45'),
('c1bd5b3d-ae15-4125-8c7d-69ad2cdc4e90','oleg-sheps','Анна К.','Тюмень, 30 лет','Олег объяснил природу негативных воздействий так, что всё стало понятно.',5,1,'2026-03-06 17:47:45'),
('c51899d2-a99c-442b-917b-c69b7a0db854','angelina-izosimova','Роман А.','Омск, 42 года','Помогла избавиться от негатива, который преследовал нашу семью три поколения.',5,1,'2026-03-06 17:47:45'),
('c5c29926-28fa-4dc0-8bc2-22fb2e6fb051','viktoriya-raidos','Олег П.','Пермь, 47 лет','Виктория нашла потерянные документы, считав информацию дистанционно. Невероятно.',5,1,'2026-03-06 17:47:45'),
('c63b02ab-1264-4be7-80a9-109ab0890ab7','vlad-cherevatyy','Наталья С.','Санкт-Петербург, 34 года','Влад создал для меня индивидуальную руническую формулу на привлечение финансов. Через месяц повысили зарплату.',5,1,'2026-03-06 17:47:45'),
('c7bf884b-7462-4969-a2b0-5edbbdc8c8a9','elena-golunova','Надежда, 48','','Мой единственный сын стремительно погибал от тяжелой зависимости. Алкоголь и запрещенные препараты превратили умного, доброго парня в агрессивного монстра. Он выносил ценные вещи из дома, постоянно скандалил, однажды даже поднял на меня руку в невменяемом состоянии. Я прошла через все мыслимые круги ада: дорогие рехабы, закрытые клиники, гипнозы, кодировки — ничего не помогало, он срывался снова и снова, падая еще ниже. Я уже с ужасом готовилась к его похоронам. Однажды в интернете я случайно наткнулась на большую статью, где упоминалась Елена Голунова. Я решила для себя, что это наш самый последний шанс на спасение. Связаться было очень сложно, очередь желающих большая, но я слезно умоляла ее помощников в Ватсап войти в положение. Нас приняли в виде исключения. Елена была очень строга и даже груба с сыном, она не жалела его, а буквально вскрыла все его глубинные страхи и внутренних демонов. Она четко увидела подселенца, который методично толкал его на саморазрушение. Был проведен мощнейший обряд изгнания этой сущности. Первые недели дома были очень тяжелыми, сына страшно ломало, но потом он резко успокоился. Прошло полтора года — он абсолютно чист, нашел хорошую работу, завел замечательную девушку. Это настоящее, рукотворное чудо!',5,1,'2026-03-23 12:19:08'),
('c8c58128-fee5-4299-882c-bd0409ebef3a','viktoriya-raidos','Кира С.','Воронеж, 38 лет','Обращаюсь к Виктории уже второй год. Её прогнозы сбываются неизменно.',5,1,'2026-03-06 17:47:45'),
('c8e0a0c3-c6dc-43bf-8781-92a760ec7c81','angelina-izosimova','Дарья М.','Самара, 29 лет','Ангелина создала для меня индивидуальный оберег. С тех пор чувствую себя защищённой.',4,1,'2026-03-06 17:47:45'),
('cc2f81c2-2455-44ce-8ea4-3d3c19a5fa8d','elena-golunova','Ирина, 41','','Никому не пожелаю пережить то, что пережила я прошлой осенью. Мой муж, с которым мы прожили душа в душу пятнадцать лет, в один день просто молча собрал вещи и ушел к молодой девице, оставив меня с двумя маленькими детьми. Он стал сам на себя не похож: стеклянные глаза, постоянная агрессия, полное равнодушие к сыновьям. Я места себе не находила, плакала сутками напролет. Сестра посмотрела на это и сказала, что это очень похоже на приворот. Я начала лихорадочно искать помощь, перерыла весь интернет, читала отзывы кто обращался. Решила, что мне нужна именно Елена Голунова. Нашла ее телефон через официальный сайт, решила написать в Ватсап. Мне ответили ее администраторы, и вскоре состоялась долгожданная консультация. Елена сразу подтвердила мои самые худшие опасения — на муже был сильнейший приворот на крови. Она взялась за нашу непростую ситуацию. Это была долгая и сложная работа, но спустя два месяца муж вернулся домой. Он плакал и просил прощения, говорил, что жил всё это время как в густом тумане.',5,1,'2026-03-23 12:19:08'),
('cc8499a6-0f3e-4d26-b406-6d93251b5f5e','zuliya-radzhabova','Светлана Г.','Краснодар, 40 лет','Зулия определила проблему со здоровьем, которую врачи не находили. Обследование подтвердило её правоту.',5,1,'2026-03-06 17:47:45'),
('ccab1ed3-22a0-4fd9-a5d1-4ace310894e1','nadezhda-shevchenko','Марина Л.','Ростов-на-Дону, 39 лет','Рекомендую Надежду всем знакомым. За три года ни одного неверного прогноза.',5,1,'2026-03-06 17:47:45'),
('cf37ecb7-1874-4a47-b43c-3d5d4d509fa6','elena-golunova','Татьяна, 52','','После скоропостижной смерти наших родителей мы с родным братом внезапно стали злейшими, непримиримыми врагами. Главный камень преткновения — оставшееся наследство. Брат, которого я всегда искренне любила и опекала, вдруг стал вести себя абсолютно неадекватно, кричал, угрожал мне судами, нанимал сомнительных людей, чтобы психологически выжить меня из родительского дома. Я просто не узнавала родного человека, в его глазах была только злоба. В полном отчаянии я начала искать помощь на стороне. Читала разные форумы, где активно обсуждались известные экстрасенсы. Многие люди настоятельно рекомендовали Елену Голунову. Я нашла адрес в Москве и записалась на личный прием, чтобы разобраться в ситуации. Елена Валерьевна очень внимательно выслушала меня, посмотрела принесенные фотографии. И сказала то, от чего я просто остолбенела: на брата оказывала мощное влияние его новая алчная жена, которая занималась черной магией, чтобы забрать всё имущество себе. Елена помогла мне выстроить надежную энергетическую защиту и снять пелену с глаз брата. Через три месяца он пришел ко мне с цветами и извинениями, мы мирно и поровну поделили имущество, а с той ужасной женщиной он со скандалом развелся.',5,1,'2026-03-23 12:19:08'),
('d312e5f1-b397-4bcf-94f5-05f176af834e','zuliya-radzhabova','Алексей Т.','Самара, 37 лет','Удивительная женщина. Её руки излучают тепло и покой. После сеанса чувствуешь себя заново рождённым.',5,1,'2026-03-06 17:47:45'),
('d793c33e-cf62-4751-9788-3770c6d2da12','elena-golunova','Яна, 33','','Я уже окончательно опустила руки и горько смирилась с тем, что буду совсем одна до конца своих дней. Каждые мои новые отношения заканчивались болезненным, жестоким предательством. Мужчины мне нагло лгали, изменяли с моими же подругами, цинично использовали меня ради моих денег и связей. Я чувствовала себя выжатым лимоном, потерявшим веру в любовь. Моя лучшая подруга, видя мои бесконечные страдания, просто взяла и подарила мне оплаченный визит к известному специалисту. Это была ясновидящая Елена Голунова. Я сначала очень разозлилась на нее, кричала, что не верю в эти средневековые сказки, но из уважения к подруге все-таки пошла. В Москве я нашла ее офис. И этот короткий визит полностью перевернул мое сознание. Елена Валерьевна не стала меня утешать и жалеть. Она очень жестко и прямо указала на мои собственные кармические ошибки из прошлых воплощений, которые я упрямо, раз за разом повторяла в этой жизни. Она дала мне специальные духовные практики для очищения и прощения себя. Это был очень болезненный, долгий, но жизненно необходимый процесс трансформации. Спустя несколько месяцев тяжелой работы над собой я встретила мужчину, который относится ко мне с таким трепетом и уважением, что я до сих пор не верю своему счастью.',5,1,'2026-03-23 12:19:08'),
('d8789f8b-de5c-491b-b710-7c48e4de4779','elena-golunova','Игорь, 40','','Я всегда считал людей, которые ходят к бабкам и ясновидящим, мягко говоря, странными и наивными. Но когда на моей любимой работе началась настоящая, целенаправленная травля, а мои крупные проекты стали срываться один за другим по абсолютно мистическим причинам (то сервер внезапно сгорит, то флешка с важной презентацией исчезнет из запертого кабинета), я серьезно задумался. Конкурент явно использовал грязные, нечестные методы, чтобы меня подсидеть. Я решил выяснить, сколько стоит прием у профессионала, и стал искать информацию в сети. Экстрасенс Елена Голунова показалась мне самым адекватным, строгим и сильным специалистом. Через официальный сайт записался на личную консультацию. Был поражен ее жестким, сугубо конкретным подходом — никакой лишней воды, никаких стеклянных шаров и театральщины. Она четко описала моего недоброжелателя, его скрытые мотивы и методы. Дала мне определенные вещи для защиты и строгие инструкции. Удивительно, но ровно через неделю этого конкурента уволили со скандалом, а мои рабочие дела снова пошли в гору.',5,1,'2026-03-23 12:19:08'),
('d87e2871-16c6-4333-802a-6155b7afeee3','elena-golunova','Ольга, 38','','Сейчас я четко понимаю, что моя встреча с этим человеком была послана мне свыше и точно не была случайной. Годами я страдала от жуткого, съедающего изнутри одиночества. Вроде бы привлекательная, успешная женщина, но мужчины бежали от меня как от огня после пары свиданий. Я чувствовала, что на мне висит какое-то невидимое клеймо. Подруги в шутку говорили про \"венец безбрачия\", а мне было совершенно не до смеха. Когда я окончательно отчаялась построить семью, решила найти контакты сильного и проверенного специалиста. Экстрасенс Елена Голунова давно вызывала у меня огромное доверие своей прямотой. Я зашла на официальный сайт, посмотрела цены приема и оставила заявку. Думала, что онлайн формат будет менее эффективным, но я сильно ошибалась. Елена Валерьевна мгновенно увидела корень моей проблемы — родовой негатив по женской линии. Она рассказала такие пугающие подробности о моей прабабушке, от которых у меня просто мурашки побежали по коже. После проведенной ею чистки моя жизнь кардинально изменилась. Я встретила замечательного мужчину, и мы уже планируем свадьбу!',5,1,'2026-03-23 12:19:08'),
('d8a4b975-3462-4508-91a3-013dfd73c12f','vlad-cherevatyy','Алексей Г.','Ростов-на-Дону, 33 года','Влад — настоящий мастер рун. Его формулы работают как швейцарские часы.',5,1,'2026-03-06 17:47:45'),
('d990169d-7a1c-46c1-bdc7-70788b80a713','nadezhda-shevchenko','Екатерина С.','Новосибирск, 27 лет','Надежда — удивительный таролог. Её расклады настолько детальны, что каждый раз удивляюсь.',5,1,'2026-03-06 17:47:45'),
('dbe3d850-290d-4704-9e67-0859786b4cb5','aleksandr-sheps','Сергей Л.','Ростов-на-Дону, 45 лет','Обратился к Александру с проблемой бессонницы. Он нашёл энергетическую причину и помог от неё избавиться.',5,1,'2026-03-06 17:47:45'),
('dd045c0e-ae84-46c3-8470-44d84434d559','elena-golunova','Виктор, 47','','Мы с женой почти два года никак не могли продать нашу трехкомнатную квартиру. Место просто отличное, ремонт свежий, цену мы снижали уже сильно ниже рыночной, но потенциальные покупатели либо срывались в самый последний момент перед сделкой, либо вообще не приходили на назначенные просмотры. Возникало стойкое ощущение, как будто место было проклято или невидимая стена стояла. А нам очень срочно нужны были большие деньги на операцию для матери. Отчаявшись, мы решили прибегнуть к нестандартным методам. Жена нашла отзывы о приеме у Голуновой и сказала, что это наш последний реальный шанс. Мы зашли на официальный сайт, посмотрели цены, взвесили всё и оставили заявку. Нам назначили онлайн-встречу. Елена сразу огорошила нас неожиданной новостью: в квартире осталась тяжелая энергетика самого первого владельца, которая просто агрессивно не пускала новых людей и гнала их прочь. Елена провела специальный обряд очищения помещения дистанционно и уверенно сказала, что продадим недвижимость в течение месяца. И что вы думаете? Через две недели пришла молодая семейная пара и купила квартиру за наличные даже без торга.',5,1,'2026-03-23 12:19:08'),
('e056e958-8857-4287-bcec-dbbdc368703f','viktoriya-raidos','Анастасия В.','Тюмень, 25 лет','После сеанса у Виктории наконец обрела покой. Она помогла отпустить прошлое.',5,1,'2026-03-06 17:47:45'),
('e338af1d-1363-4a7d-bbde-d3750bc45d1b','nadezhda-shevchenko','Дарья Т.','Омск, 29 лет','Надежда Шевченко изменила моё отношение к жизни одним раскладом.',5,1,'2026-03-06 17:47:45'),
('e977449b-bc77-4b21-92bd-75907d4667ef','vlad-cherevatyy','Мария Д.','Екатеринбург, 40 лет','Рунический оберег от Влада защищает всю мою семью. Атмосфера в доме изменилась кардинально.',5,1,'2026-03-06 17:47:45'),
('f3cefac5-6c7b-45c4-858f-4faa93a5de48','elena-golunova','Светлана, 29','','Если честно, я вообще не верила во всю эту мистику, магию и экстрасенсов, пока сама не столкнулась с абсолютно необъяснимым явлением. У меня начались дикие боли в спине, такие, что я иногда просто не могла встать с кровати по утрам. Врачи разводили руками: анализы идеальные, МРТ чистое, патологий нет. Я обошла всех светил, потратила кучу денег на обследования, а толку ноль. Однажды мамина подруга обмолвилась, что мне нужна сибирская ведьма, мол, это явно чужое вмешательство. Я от безысходности стала искать в сети, кто реально может помочь с таким. Так я вышла на Елену Валерьевну. Записаться было непросто, пришлось подождать своей очереди. На приеме она сразу, без лишних слов, сказала, что проблема не в физическом здоровье, а в черной зависти коллеги, которая метила на мое место и сделала крадник. Я была в шоке, потому что действительно недавно получила серьезное повышение. После работы с Еленой все боли ушли за пару недель. Я вернулась к нормальной жизни.',5,1,'2026-03-23 12:19:08'),
('f5474fe7-266d-41bb-b681-708e043b2a55','viktoriya-raidos','Сергей Д.','Новосибирск, 46 лет','Победительница 17 сезона полностью оправдывает свой титул. Виктория видит то, что невозможно увидеть.',5,1,'2026-03-06 17:47:45'),
('fc63286b-145b-4c79-bb88-6905c7fcbf49','angelina-izosimova','Виктор К.','Тюмень, 44 года','Обращался дважды. Оба раза — точная диагностика и реальный результат.',5,1,'2026-03-06 17:47:45'),
('fdfd027b-ed16-438e-b54e-e282794f04f9','angelina-izosimova','Павел Р.','Санкт-Петербург, 43 года','Потомственная ведьма — это чувствуется по силе её ритуалов. Ангелина сняла порчу, которую другие не могли обнаружить.',5,1,'2026-03-06 17:47:45'),
('ff83224a-51d2-4807-add0-6eb657f001d9','elena-golunova','Наталья, 50','','Земля буквально ушла из-под ног, когда моя пятнадцатилетняя дочь не вернулась домой после школы. Телефон был недоступен, лучшие друзья ничего не знали и плакали вместе со мной. Полиция неохотно приняла заявление, но драгоценное время шло, а результатов поисков не было никаких. Я не могла ни есть, ни спать, просто сходила с ума от страшной неизвестности. В полиции уже аккуратно намекали на самое худшее. Моя родная сестра буквально силой заставила меня искать альтернативные пути и не сдаваться. Мы стали искать информацию, кто может помочь в таких бедах. Нашли официальный адрес и контакты Елены Валерьевны. Нам чудом повезло быстро попасть к ней на прием со срочной бедой. Я принесла свежую фотографию дочери. Елена посмотрела на нее, закрыла глаза и сразу уверенно сказала: \"Жива. Находится в казенном старом доме, совсем рядом вода\". Она детально описала местность и сказала, что девочка сбежала из-за скрытого конфликта в школе. Мы тут же передали информацию нашему следователю, и на следующий день дочь действительно нашли именно в том районе, на заброшенной лодочной станции. Эта сибирская ведьма просто спасла моего ребенка!',5,1,'2026-03-23 12:19:08'),
('ffcb323d-204c-4105-bd10-dd1e2ee4561f','elena-golunova','Денис, 31','','Хочу выразить огромную, искреннюю благодарность за то, что меня буквально вернули к нормальной жизни из полного мрака. Последние три года я мучился от жесточайших панических атак. Они накатывали внезапно: в метро, на работе, за рулем машины. Я не мог нормально дышать, сердце выпрыгивало из груди, темнело в глазах. Психотерапевты и тяжелые таблетки давали лишь временный, легкий эффект. Я постепенно стал затворником, боялся выйти на улицу. Моя девушка, видя мои ежедневные мучения, решила действовать сама. Она знала, что Елена Голунова помогла очень многим, так как мы вместе смотрели эфиры. Она нашла, где принимает специалист в Москве, и чудом смогла записать меня на ближайшее время. Я шел туда с огромным недоверием и долей иронии. Но колдунья даже не стала меня долго слушать, она сама мне всё рассказала. Оказалось, я случайно \"подцепил\" сущность на старом кладбище в Рязани, где мы гуляли с друзьями в юности. После ее вмешательства приступы как рукой сняло. Прошло уже восемь месяцев — ни одной панической атаки!',5,1,'2026-03-23 12:19:08');
